cat > .local/seven-smart-2026-10-20/probe-source.ts <<'EOF'
import{readFile,writeFile}from'node:fs/promises';
import{CanonicalClassicSession}from'../../classic/apps/web/src/core/canonical-classic-session';
import{createCanonicalTestRuntime}from'../../classic/apps/web/src/core/__tests__/canonical-runtime-fixture';
const doc=JSON.parse(await readFile('.local/seven-smart-2026-10-20/project-before-extract.json','utf8'));delete doc.__opencutEditorSession;
const mediaAssets=JSON.parse(await readFile('.local/seven-smart-2026-10-20/media-before.json','utf8'));
const rt=await createCanonicalTestRuntime();try{
const session=new CanonicalClassicSession({runtime:rt,projectId:doc.metadata.id});session.attach({classic:{document:doc,mediaAssets}});
const source=session.preparePodcast({sceneId:'multicam-scene-1',elementIds:[]});
await writeFile('.local/seven-smart-2026-10-20/prepared-before-fix.json',JSON.stringify(source));
const moved=source.words.filter(w=>w.id!==w.sourceIndex);console.log('word count',source.words.length,'moved',moved.length,'examples',JSON.stringify(moved.slice(0,8)));
const firstDiff=source.words.findIndex(w=>w.id!==w.sourceIndex);console.log(JSON.stringify(source.words.slice(Math.max(0,firstDiff-2),firstDiff+4)));
const video={title:'Probe',openingHook:'Known source',endingHook:'Complete thought',confidence:.9,alternatives:[{label:'Probe',reason:'No inference',parts:[{firstWord:80,lastWord:180}]}]};
try{session.podcast({sceneId:'multicam-scene-1',elementIds:[],expectedRevision:source.revision,options:{mode:'highlights',minSeconds:20,maxSeconds:90,maxOutputs:1},videos:[video]});console.log('compaction passed');}catch(e){console.log('compaction failed:',String(e));}
}finally{rt.free();}
EOF
bun run .local/seven-smart-2026-10-20/probe-source.ts > .local/seven-smart-2026-10-20/compaction-probe.log 2>&1
